is_balanced:
def is_balanced(s):
    stack = []
    brackets = {'(': ')', '[': ']', '{': '}'}

    for char in s:
        if char in brackets:
            stack.append(char)
        elif char in brackets.values():
            if not stack or brackets[stack.pop()] != char:
                return False
    return not stack

two_sum:
def two_sum(nums, target):
    num_to_index = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return [num_to_index[complement], i]
        num_to_index[num] = i
    return []

roman_to_int:
def roman_to_int(s):
    roman_dict = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }
    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman_dict[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

merge_intervals:
def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals based on start time
    intervals.sort(key=lambda x: x[0])

    merged = [intervals[0]]
    for current in intervals[1:]:
        last = merged[-1]
        if current[0] <= last[1]:  # Overlapping or adjacent
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
            merged.append(current)

    return merged

longest_unique:
def longest_unique(s):
    char_index = {}
    max_length = 0
    start = 0

    for end, char in enumerate(s):
        if char in char_index and char_index[char] >= start:
            start = char_index[char] + 1
        char_index[char] = end
        max_length = max(max_length, end - start + 1)

    return max_length

spiral_order:
def spiral_order(matrix):
    result = []
    if not matrix or not matrix[0]:
        return result

    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1

    while top <= bottom and left <= right:
        # Traverse from left to right
        for i in range(left, right + 1):
            result.append(matrix[top][i])
        top += 1

        # Traverse from top to bottom
        for i in range(top, bottom + 1):
            result.append(matrix[i][right])
        right -= 1

        # Traverse from right to left
        if top <= bottom:
            for i in range(right, left - 1, -1):
                result.append(matrix[bottom][i])
            bottom -= 1

        # Traverse from bottom to top
        if left <= right:
            for i in range(bottom, top - 1, -1):
                result.append(matrix[i][left])
            left += 1

    return result

word_break:
def word_break(s, word_dict):
    word_set = set(word_dict)
    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True  # Empty string is valid

    for i in range(1, n + 1):
        for j in range(i):
            if dp[j] and s[j:i] in word_set:
                dp[i] = True
                break

    return dp[n]

coin_change:
def coin_change(coins, amount):
    # Initialize dp array with infinity for all amounts
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0  # Base case: 0 coins needed to make 0 amount

    for coin in coins:
        for a in range(coin, amount + 1):
            dp[a] = min(dp[a], dp[a - coin] + 1)

    return dp[amount] if dp[amount] != float('inf') else -1

lru_cache:
from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.cache = OrderedDict()
        self.capacity = capacity

    def get(self, key):
        if key not in self.cache:
            return -1
        value = self.cache.pop(key)
        self.cache[key] = value  # move to end to mark as most recently used
        return value

    def put(self, key, value):
        if key in self.cache:
            self.cache.pop(key)
        elif len(self.cache) >= self.capacity:
            self.cache.popitem(last=False)  # remove least recently used item
        self.cache[key] = value

edit_distance:
def edit_distance(a, b):
    m = len(a)
    n = len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],    # delete
                                   dp[i][j - 1],    # insert
                                   dp[i - 1][j - 1])  # replace

    return dp[m][n]

trap_rain:
def trap_rain(height):
    if not height:
        return 0

    n = len(height)
    left = [0] * n
    right = [0] * n

    left[0] = height[0]
    for i in range(1, n):
        left[i] = max(left[i - 1], height[i])

    right[n - 1] = height[n - 1]
    for i in range(n - 2, -1, -1):
        right[i] = max(right[i + 1], height[i])

    water_trapped = 0
    for i in range(n):
        water_trapped += min(left[i], right[i]) - height[i]

    return water_trapped

median_two_sorted:
def median_two_sorted(a, b):
    # Ensure a is the smaller list
    if len(a) > len(b):
        a, b = b, a

    total = len(a) + len(b)
    half = total // 2

    left, right = 0, len(a) - 1
    while left <= right:
        i = (left + right) // 2
        j = half - i - 1

        a_left = a[i] if i < len(a) else float('inf')
        a_right = a[i + 1] if i + 1 < len(a) else float('inf')
        b_left = b[j] if j >= 0 else -float('inf')
        b_right = b[j + 1] if j + 1 < len(b) else float('inf')

        if b_left <= a_right and a_left <= b_right:
            if total % 2 == 1:
                return min(a_right, b_right)
            else:
                return (max(a_left, b_left) + min(a_right, b_right)) / 2
        elif b_left > a_right:
            left = i + 1
        else:
            right = i - 1

regex_match:
def regex_match(s: str, p: str) -> bool:
    memo = {}

    def dp(i: int, j: int) -> bool:
        if (i, j) in memo:
            return memo[(i, j)]

        if j == len(p):
            return i == len(s)

        first_match = i < len(s) and p[j] in {'.', s[i]}

        if j + 1 < len(p) and p[j + 1] == '*':
            res = (dp(i, j + 2) or  # Skip this pattern
                   first_match and dp(i + 1, j))  # Use it
        else:
            res = first_match and dp(i + 1, j + 1)

        memo[(i, j)] = res
        return res

    return dp(0, 0)

n_queens:
def n_queens(n):
    def backtrack(row, cols, pos_diag, neg_diag):
        if row == n:
            return 1
        solutions = 0
        for col in range(n):
            p = row + col
            ng = row - col
            if col in cols or p in pos_diag or ng in neg_diag:
                continue
            cols.add(col)
            pos_diag.add(p)
            neg_diag.add(ng)
            solutions += backtrack(row + 1, cols, pos_diag, neg_diag)
            cols.remove(col)
            pos_diag.remove(p)
            neg_diag.remove(ng)
        return solutions

    return backtrack(0, set(), set(), set())

calculate:
def calculate(s: str) -> int:
    def helper(s: list) -> int:
        num = 0
        sign = 1
        stack = []
        i = 0
        while i < len(s):
            c = s[i]
            if c.isdigit():
                num = num * 10 + int(c)
            if c in '+-*/' or i == len(s) - 1:
                if i < len(s) - 1 or c != ')':
                    num *= sign
                    stack.append(num)
                num = 0
                if c == '+':
                    sign = 1
                elif c == '-':
                    sign = -1
                elif c == '*':
                    prev = stack.pop()
                    stack.append(prev * num)
                elif c == '/':
                    prev = stack.pop()
                    stack.append(int(prev / num))  # Truncate toward zero
                elif c == '(':
                    j = i + 1
                    count = 1
                    while count > 0:
                        if s[j] == '(':
                            count += 1
                        elif s[j] == ')':
                            count -= 1
                        j += 1
                    stack.append(helper(s[i+1:j-1]))
                    i = j - 1
                num = 0
            i += 1
        return sum(stack)

    return helper(s.replace(' ', ''))

lis_length:
def lis_length(nums):
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

min_path_sum:
def min_path_sum(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    for i in range(1, m):
        grid[i][0] += grid[i-1][0]
    for j in range(1, n):
        grid[0][j] += grid[0][j-1]

    for i in range(1, m):
        for j in range(1, n):
            grid[i][j] += min(grid[i-1][j], grid[i][j-1])

    return grid[-1][-1]

decode_ways:
def decode_ways(s):
    if not s or s[0] == '0':
        return 0

    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1

    for i in range(2, n + 1):
        # Check single digit
        if s[i - 1] != '0':
            dp[i] += dp[i - 1]
        # Check two digits
        two_digit = int(s[i - 2:i])
        if 10 <= two_digit <= 26:
            dp[i] += dp[i - 2]

    return dp[n]
